import networkx as nx
G = nx.Graph()
for i in range(25):
    G.add_node(i)
for i in range(25):
    for j in range(i+1, 25):
        if len(list(G.neighbors(i))) < 4 and len(list(G.neighbors(j))) < 4:
            G.add_edge(i, j)
            if len(list(G.neighbors(i))) == 4:
                break
print(list(G.edges))
